       floor: runIdleTimeout,
       explicitIdle: explicit?.$1,
     );
+    final scale = payloadStallScaleFor(lastOutboundEstimateBytes);
+    final window = Duration(
+      milliseconds: (resolved.inMilliseconds * scale).round(),
+    );
     return (
       window: window,
       source: explicit?.$2 ?? 'default',
