// SCRATCH REVIEW VERIFICATION — deleted after the review run.
// Reproduces: an abandoned connect attempt whose send future completes
// with an ERROR (not a response) during the retry-backoff adoption race.
import 'dart:async';

import 'package:flutter_agent_harness/src/providers/provider_common.dart';
import 'package:flutter_agent_harness/src/providers/provider_tuning.dart'
    show providerConnectRetryBackoff, providerConnectRetries;
import 'package:http/http.dart' as http;
import 'package:test/test.dart';

final class _ErrThenOkClient extends http.BaseClient {
  var count = 0;
  @override
  Future<http.StreamedResponse> send(http.BaseRequest request) {
    count++;
    if (count == 1) {
      // Answers with an ERROR 30ms in: after the 20ms watchdog, inside
      // the 50ms backoff — exactly the adoption-race window.
      return Future<http.StreamedResponse>.delayed(
        const Duration(milliseconds: 30),
        () => throw StateError('simulated late transport failure'),
      );
    }
    return Future.value(
      http.StreamedResponse(
        Stream.value(utf8.encode('ok')),
        200,
        headers: {'content-type': 'text/event-stream'},
      ),
    );
  }
}

void main() {
  test('SCRATCH: late ERROR from an abandoned attempt during the backoff',
      () async {
    providerConnectRetryBackoff = const Duration(milliseconds: 50);
    final client = _ErrThenOkClient();
    final request = http.Request(
      'POST',
      Uri.parse('https://api.example.com/v1/chat/completions'),
    )..body = '{}';
    Object? error;
    try {
      await sendWatchedProviderRequest(
        client,
        request,
        null,
        connectTimeout: const Duration(milliseconds: 20),
      );
    } catch (e) {
      error = e;
    }
    // ignore: avoid_print
    print('ERROR-TYPE: ${error.runtimeType}');
    // ignore: avoid_print
    print('SENT: ${client.count}');
    // ignore: avoid_print
    print('IS-TIMEOUT: ${error is TimeoutException}');
    // ignore: avoid_print
    print('IS-STATEERROR: ${error is StateError}');
  });
}

